import{_ as e,o as a,c as r,a3 as n}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"领域 Agent 架构","description":"比较浏览器、代码、研究、多模态、数据和实时语音任务的观察、动作、状态、安全与验证边界。","frontmatter":{"title":"领域 Agent 架构","description":"比较浏览器、代码、研究、多模态、数据和实时语音任务的观察、动作、状态、安全与验证边界。"},"headers":[],"relativePath":"py-agent/architecture/domain-agent-architectures/index.md","filePath":"py-agent/architecture/domain-agent-architectures/index.md","lastUpdated":1786083160000}'),i={name:"py-agent/architecture/domain-agent-architectures/index.md"};function d(o,t,l,c,h,g){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="领域-agent-架构" tabindex="-1">领域 Agent 架构 <a class="header-anchor" href="#领域-agent-架构" aria-label="Permalink to &quot;领域 Agent 架构&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>Agent 的通用循环相似，但运行环境并不相同：网页元素会变化，代码修改需要 Patch 和测试，研究结论依赖可追踪证据，SQL 必须受语义和权限约束，语音还要处理轮次与打断。本分组提供六类可复用参考架构，帮助你识别领域差异怎样改变系统设计。</p><h2 id="_1-学习目标" tabindex="-1">1. 学习目标 <a class="header-anchor" href="#_1-学习目标" aria-label="Permalink to &quot;1. 学习目标&quot;">​</a></h2><p>完成本分组后，你应该能够：</p><ol><li>为领域任务定义观察、动作、状态、制品和成功 Oracle；</li><li>判断模型负责开放决策还是确定工具负责执行与验证；</li><li>识别每类 Agent 特有的权限、注入、隐私和副作用风险；</li><li>设计停止、取消、恢复、预算和人工接管；</li><li>为领域 Agent 建立阶段指标与端到端任务评测；</li><li>组合多个参考架构，而不把所有能力塞进一个万能 Agent。</li></ol><h2 id="_2-领域地图" tabindex="-1">2. 领域地图 <a class="header-anchor" href="#_2-领域地图" aria-label="Permalink to &quot;2. 领域地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文章</th><th>主要环境</th><th>核心状态</th><th>完成证据</th></tr></thead><tbody><tr><td><a href="/py-agent/architecture/domain-agent-architectures/browser-agent">浏览器 Agent</a></td><td>动态网页、DOM、视觉和会话</td><td>URL、页面观察、动作历史、下载制品</td><td>页面或业务系统的可验证变化</td></tr><tr><td><a href="/py-agent/architecture/domain-agent-architectures/coding-agent">代码 Agent</a></td><td>仓库、文件、命令和 Git</td><td>Repo Revision、Patch、命令与测试结果</td><td>可审查 Diff 和验证报告</td></tr><tr><td><a href="/py-agent/architecture/domain-agent-architectures/research-agent">研究型 Agent</a></td><td>开放来源、查询和证据</td><td>子问题、来源、Evidence、Claim 和缺口</td><td>带可定位引用的结论</td></tr><tr><td><a href="/py-agent/architecture/domain-agent-architectures/multimodal-agent">多模态 Agent</a></td><td>图片、文档、音频和视频</td><td>Artifact、Segment、坐标、派生结果</td><td>可回到原始位置的结果</td></tr><tr><td><a href="/py-agent/architecture/domain-agent-architectures/data-sql-agent">数据与 SQL Agent</a></td><td>语义目录、数据库和查询网关</td><td>指标、过滤、SQL、查询与结果</td><td>受治理口径下的业务结果</td></tr><tr><td><a href="/py-agent/architecture/domain-agent-architectures/voice-realtime-agent">实时语音 Agent</a></td><td>持续音频、实时事件和电话网络</td><td>Transcript、轮次、播放范围、Slot 和工具状态</td><td>用户实际听到且业务确认的结果</td></tr></tbody></table><p>这些文章不是按难度递增的必修顺序。应优先阅读与你的产品环境最接近的一篇，再用其他文章补充跨领域能力。</p><h2 id="_3-共同分析框架" tabindex="-1">3. 共同分析框架 <a class="header-anchor" href="#_3-共同分析框架" aria-label="Permalink to &quot;3. 共同分析框架&quot;">​</a></h2><p>阅读或设计任何领域 Agent 时，统一检查：</p><ol><li><strong>任务边界</strong>：哪些任务只读，哪些会产生外部副作用；</li><li><strong>观察模型</strong>：模型实际看见 DOM、文件、证据、媒体片段、Schema 还是音频事件；</li><li><strong>动作协议</strong>：允许哪些受限动作，参数和返回如何结构化；</li><li><strong>状态与制品</strong>：哪些信息进入 State，哪些大对象只保存引用；</li><li><strong>验证与终止</strong>：什么事实证明目标达成，何时停止、转人工或安全失败；</li><li><strong>安全边界</strong>：不可信内容、身份、网络、文件和工具权限在哪里强制；</li><li><strong>评测</strong>：阶段错误和端到端任务成功怎样分别测量。</li></ol><p>共同框架用于比较，不代表六类 Agent 使用相同工具或数据模型。</p><h2 id="_4-组合方式" tabindex="-1">4. 组合方式 <a class="header-anchor" href="#_4-组合方式" aria-label="Permalink to &quot;4. 组合方式&quot;">​</a></h2><p>真实系统可能组合多个领域。例如研究 Agent 使用浏览器发现来源、用多模态管线解析 PDF，再让代码 Agent 生成分析脚本。组合时传递结构化任务、Artifact ID、允许权限和预期产物，不直接倾倒完整上下文。</p><p>每增加一种领域能力，都要重新评估外部网络、文件、Secret、租户数据、预算和终止条件。角色名称或 Prompt 不能成为安全边界。</p><h2 id="_5-分组边界" tabindex="-1">5. 分组边界 <a class="header-anchor" href="#_5-分组边界" aria-label="Permalink to &quot;5. 分组边界&quot;">​</a></h2><p>本组解释参考架构，不提供六个完整项目，也不重复 Playwright、Git、SQL、OCR、WebRTC 等技术的百科教程。需要完整代码、测试和部署时进入“项目实战”；需要框架 API 时回到对应专题模块。</p><p>一篇领域文章的目标是让读者能够画出可信的数据与控制流、定义关键契约和验证结果，而不是仅记住该领域可以调用哪些工具。</p>',19)])])}const u=e(i,[["render",d]]);export{p as __pageData,u as default};
